import { beforeEach, describe, expect, it, vi } from "vitest";
import { captureFromHook } from "../chatSessions/index.js";
import { runCaptureHook } from "./captureHook.js";
vi.mock("../chatSessions/index.js", () => ({
    captureFromHook: vi.fn(),
}));
const STOP_INPUT = {
    session_id: "capture-hook-session",
    transcript_path: "/tmp/transcript.jsonl",
};
describe("runCaptureHook", () => {
    beforeEach(() => {
        vi.mocked(captureFromHook).mockReset();
    });
    it("hands the hook input to session capture and writes nothing to stdout", async () => {
        vi.mocked(captureFromHook).mockResolvedValue({ status: "no_op" });
        const write = vi.spyOn(process.stdout, "write");
        await runCaptureHook("Stop", "cursor", STOP_INPUT, "1.2.3");
        expect(captureFromHook).toHaveBeenCalledWith("Stop", STOP_INPUT, "cursor", "1.2.3");
        expect(write).not.toHaveBeenCalled();
        write.mockRestore();
    });
    it("does nothing without a session id", async () => {
        await runCaptureHook("Stop", "claude-code", {
            ...STOP_INPUT,
            session_id: "",
        });
        expect(captureFromHook).not.toHaveBeenCalled();
    });
    it("swallows a capture failure so the host's hook never fails", async () => {
        vi.mocked(captureFromHook).mockRejectedValue(new Error("offline"));
        await expect(runCaptureHook("Stop", "codex", STOP_INPUT)).resolves.toBeUndefined();
    });
});
